export function renderOfferPanel(state,e){
  if(!state.enabled)return '';
  const fields=state.draft?.fields||{};
  const inputs=[['product','What are you selling?',500,true],['exactTerm','Specific model or product name (optional)',80,false],['location','Where can you sell it?',120,true],['price','Asking price and currency',250,false],['condition','Condition or service scope',250,false],['quantity','Quantity or availability',250,false],['delivery','Delivery or inspection options',250,false]];
  const input=([name,label,max,required])=>`<div class="field"><label for="offer-${name}">${label}</label><input id="offer-${name}" name="${name}" maxlength="${max}" value="${e(name==='exactTerm'?state.draft?.exactTerm||'':fields[name]||'')}" ${required?'required':''}></div>`;
  return `<section class="panel offer-panel"><div class="panel-head"><div><h2>Start with what you sell.</h2><p>Confirm the details once. Pull will use this version when looking for possible buyers.</p></div></div>
  <form id="offer-form" class="account-form" aria-busy="${Boolean(state.busy)}"><fieldset ${state.busy?'disabled':''} aria-label="Selling details"><div class="section-grid">${inputs.filter(([name])=>['product','location','price'].includes(name)).map(input).join('')}</div><details ${state.error?'open':''}><summary>Add condition, quantity or delivery details</summary><div class="section-grid">${inputs.filter(([name])=>!['product','location','price'].includes(name)).map(input).join('')}</div></details><p class="small-print">Confirm that these are your current selling terms. Saving keeps this offer in your account.</p><div class="form-actions"><button class="button primary" type="submit" ${state.busy?'disabled':''}>${state.busy?'Saving…':state.draft?.version?'Confirm updated details':'Confirm and save'}</button>${state.draft?.version?`<button class="button secondary" type="button" data-action="offer-new" ${state.busy?'disabled':''}>New product</button>`:''}</div></fieldset></form>
  ${state.error?`<p class="form-error" role="alert">${e(state.error)}</p>`:''}${state.notice?`<p role="status">${e(state.notice)}</p>`:''}
  ${state.offers?.length?`<div class="panel-head"><h3>Your saved offers</h3><button class="link-button" data-action="offer-refresh" ${state.busy?'disabled':''}>Refresh</button></div><ul class="offer-list">${state.offers.map(o=>`<li><div><strong>${e(o.fields.product)}</strong><p>${e([o.fields.location,o.fields.price].filter(Boolean).join(' · '))}</p><small>Saved version ${e(o.version)}</small></div><div class="form-actions">${state.reviewsEnabled?`<button class="button secondary small" data-offer-reviews="${e(o.id)}">Your reviews</button>`:''}<button class="button secondary small" data-offer-edit="${e(o.id)}">Edit details</button><button class="button primary small" data-offer-research="${e(o.id)}" ${state.busy?'disabled':''}>Look for buyers</button></div></li>`).join('')}</ul>`:''}</section>`;
}
